            setName(e.target.value);
            signIn.reset();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="signin-submit" disabled={signIn.isPending}>
        Sign in
      </button>
      {signIn.isError && (
        <p data-testid="signin-error" role="alert">
          {signIn.error.message}
        </p>
      )}
    </form>
